from threetears.evals import Eval

from departures import load_timetable, next_departures

TIMETABLE = load_timetable("data/timetable.json")


def answer(case):
    """The departures the planner gives for the stop and the time asked."""
    return {"shown": next_departures(TIMETABLE, case["stop"], case["asked_at"])}


def as_shown(case, out):
    """The departures are the ones the old planner showed."""
    return out["shown"] == case["shown"]

questions = Eval("data/answers.jsonl", runner=answer, grader=[as_shown], k=1)
